/* @lc app=leetcode id=1219 lang=kotlin */ class Solution { fun put(g: Array<IntArray>, r: Int, c: Int, v: Int) { g[r][c] = v } fun dfs(g: Array<IntArray>, r: Int, c: Int): Int = if (r !in g.indices || c !in g[0].indices || g[r][c] == 0) 0 else g[r][c].let { v -> put(g, r, c, 0).let { listOf(1 to 0, -1 to 0, 0 to 1, 0 to -1).maxOf { (dr, dc) -> dfs(g, r + dr, c + dc) } }.let { best -> put(g, r, c, v).let { v + best } } } fun getMaximumGold(grid: Array<IntArray>): Int = grid.indices.maxOf { r -> grid[0].indices.maxOf { c -> dfs(grid, r, c) } } }